export type HistoricalReplayInput=Omit<CandidateReviewInput,'mode'>&{mode:'historical_replay_review_only';caseId:string};
export type HistoricalReplayEvidence={version:'historical-replay-v66';caseId:string;sourceHash:string;signedEvidenceHash:string;evidenceSnapshot:string;assetEvidenceSnapshots:Record<string,string>;variantHashScheme:'single-text-or-json-paragraphs-v1';variantSourceHashes:Record<string,string>;fieldValuesHash:string;boundSnapshotHash:string};
