  const scope=span.assetScopeKey??span.fieldKey.match(/^(asset[12])\./)?.[1],fieldAsset=scope?data.assetIds?.[scope]:undefined;if(scope&&!fieldAsset||context.assetId&&fieldAsset&&context.assetId!==fieldAsset)throw Error('fact_span_asset_scope_mismatch');const expectedAsset=context.assetId??fieldAsset;let assetEvidence=false;
